use vstd::prelude::*;

verus! {

fn concat(a: &[i32], b: &[i32]) -> (out: Vec<i32>)
    ensures
        out@.len() == a@.len() + b@.len(),
        forall|i: int|
            0 <= i < a@.len() ==>
                out@[i] == a@[i],
        forall|j: int|
            0 <= j < b@.len() ==>
                out@[a@.len() + j] == b@[j],
{
    let mut out: Vec<i32> = Vec::new();

    let mut i: usize = 0;
    while i < a.len()
        invariant
            0 <= i <= a@.len(),
            out@.len() == i as int,
            forall|k: int| 0 <= k < i as int ==> out@[k] == a@[k],
        decreases a@.len() - i as int,
    {
        out.push(a[i]);
        i += 1;
    }

    let a_len_int: int = a@.len();

    let mut j: usize = 0;
    while j < b.len()
        invariant
            0 <= j <= b@.len(),
            out@.len() == a_len_int + j as int,
            forall|k: int| 0 <= k < a_len_int ==> out@[k] == a@[k],
            forall|t: int| 0 <= t < j as int ==> out@[a_len_int + t] == b@[t],
        decreases b@.len() - j as int,
    {
        out.push(b[j]);
        j += 1;
    }

    out
}

} // verus!
